import{_ as n,C as t,o,c as s,E as r,a2 as c}from"./chunks/framework.uPk2SrVb.js";const v=JSON.parse(`{"title":"A review outcome can hide two different errors","description":"","frontmatter":{"title":"A review outcome can hide two different errors","date":"2026-10-28","column":"open-source-engineering","category":"academic","article_type":"research-note","edition":"research-center","research_question":"送审指标合并不同参考类别时，会隐藏什么？","summary":"A runnable metric audit returns 0.0067 from inputs reconstructed from a paper's narrative, while its table reports 0.0267. The cause remains unresolved; the discrepancy shows why review metrics need the original reference class.","sources":["https://arxiv.org/html/2609.37457v1","https://github.com/vtavakkoli/veriweave-govern/tree/77cf503e6cfaf35bc9e0dc7f03faa6bc832d02ec","https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents"],"pageClass":"runtime-v6-article","item_id":"academic-metric-boundaries","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-28-academic-metric-boundaries-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-10-28-academic-metric-boundaries.md","filePath":"en/engineering/2026-10-28-academic-metric-boundaries.md","lastUpdated":null}`),d={name:"en/engineering/2026-10-28-academic-metric-boundaries.md"};function l(h,e,u,p,m,f){const i=t("ArticleCover"),a=t("ArticleTableScroll");return o(),s("div",null,[r(i,{image:"/assets/covers/daily-2026-10-28-academic-metric-boundaries-cover.png",kicker:"Research",title:"A review outcome can hide two different errors",summary:"A runnable metric audit returns 0.0067 from inputs reconstructed from a paper's narrative, while its table reports 0.0267. The cause remains unresolved; the discrepancy shows why review metrics need the original reference class.",version:"2026-10-28",languageHref:"/zh/engineering/2026-10-28-academic-metric-boundaries",languageLabel:"中文"}),r(a,{language:"en"}),e[0]||(e[0]=c('<h1 id="a-review-outcome-can-hide-two-different-errors" tabindex="-1">A review outcome can hide two different errors <a class="header-anchor" href="#a-review-outcome-can-hide-two-different-errors" aria-label="Permalink to &quot;A review outcome can hide two different errors&quot;">​</a></h1><p>Sending a permitted operation to a human can add delay. Sending a prohibited operation to a human changes a refusal into a different decision. Both end in review, but they displace different reference answers. Evaluating agent authorization requires retaining that distinction alongside the final outcome.</p><p>We followed a small numerical discrepancy through a governance paper and its public metric function. The audit is runnable. It does not establish which record from the original experiment needs correction.</p><h2 id="the-same-output-different-reference-answers" tabindex="-1">The same output, different reference answers <a class="header-anchor" href="#the-same-output-different-reference-answers" aria-label="Permalink to &quot;The same output, different reference answers&quot;">​</a></h2><p>The VeriWeave Govern paper defines false-review rate as cases whose reference answer is allow but whose prediction is review, divided by all cases. Elsewhere, it describes four model errors: one allow-to-review and three deny-to-review transitions. Its table reports a false-review rate of 0.0267. <a href="https://arxiv.org/html/2609.37457v1" target="_blank" rel="noreferrer">Equation 8, Table 13 and section 5.4</a></p><p>These statements permit a conditional arithmetic check. <strong>If the error-direction narrative is complete and correct</strong>, the narrow numerator is one. Counting every non-review reference answer changed to review gives four. Sharing a denominator does not make those numerators describe the same metric.</p><table tabindex="0"><thead><tr><th>Reference → prediction</th><th style="text-align:right;">Reconstructed count</th><th>Included in the stated false-review definition</th></tr></thead><tbody><tr><td>Allow → review</td><td style="text-align:right;">1</td><td>Yes</td></tr><tr><td>Deny → review</td><td style="text-align:right;">3</td><td>No; report separately</td></tr><tr><td>Correct decision → same decision</td><td style="text-align:right;">146</td><td>No</td></tr></tbody></table><p>This table is an internal reconstruction from the narrative, not the authors&#39; original row-level predictions or newly collected task data. Review is not execution: a deny-to-review error does not by itself establish an unauthorized side effect.</p><h2 id="running-the-pinned-metric-function" tabindex="-1">Running the pinned metric function <a class="header-anchor" href="#running-the-pinned-metric-function" aria-label="Permalink to &quot;Running the pinned metric function&quot;">​</a></h2><p>The <a href="https://github.com/vtavakkoli/veriweave-govern/blob/77cf503e6cfaf35bc9e0dc7f03faa6bc832d02ec/research/metrics.py" target="_blank" rel="noreferrer">code revision we inspected</a> counts only allow-to-review transitions in its false-review function, matching the equation. Our internal probe executes that function directly. A broader count is computed separately to explain the difference; the upstream function is unchanged.</p><p>On the 150 reconstructed entries, the narrow rate is <code>1/150 = 0.0067</code>; the broader rate is <code>4/150 = 0.0267</code>. Accuracy and macro-F1, the average of class-level F1 scores, are <code>0.9733</code> and <code>0.9573</code>, matching the corresponding aggregates. This is a consistency check, not recovery of the original case identities.</p><p>Two controls help bound the result. Reconstructing the deterministic systems&#39; reported error directions returns <code>30/150 = 0.2000</code> false reviews. An intentionally uninformative all-review control has zero false allows but accuracy of only <code>0.1333</code>. That control is not a measured system result. It demonstrates why zero false allows alone cannot distinguish useful discrimination from delegating every decision to people.</p><p>Download the <a href="/joinwell52/assets/evidence/2026-10-28-academic-metric-boundaries/metric-audit.zip">minimal audit package</a>, extract it, and run <code>python audit.py</code>. It includes the upstream function, license, explicitly reconstructed inputs and expected output. It computes classification counts without calling a model or starting the authors&#39; governance service.</p><h2 id="a-discrepancy-without-a-completed-attribution" tabindex="-1">A discrepancy without a completed attribution <a class="header-anchor" href="#a-discrepancy-without-a-completed-attribution" aria-label="Permalink to &quot;A discrepancy without a completed attribution&quot;">​</a></h2><p>The public <a href="https://github.com/vtavakkoli/veriweave-govern/blob/77cf503e6cfaf35bc9e0dc7f03faa6bc832d02ec/results/paper-2026/README.md" target="_blank" rel="noreferrer">paper-results description</a> says its aggregates were transcribed from the manuscript and do not replace original predictions or annotations. The complete repository tree we inspected lacks the completed prediction and annotation files for that run. We therefore cannot determine whether the table, narrative, or historical metric version explains the difference, or revise the model ranking from this audit.</p><p>The paper, author repository and transcribed manifest belong to one research source. Their agreement helps trace provenance but is not independent empirical validation. Our probe is internal experimental evidence; we obtained no third-party replication of the original experiment. Accessibility, formal publication and peer review cannot supply that missing evidence automatically.</p><h2 id="retain-the-direction-of-each-error" tabindex="-1">Retain the direction of each error <a class="header-anchor" href="#retain-the-direction-of-each-error" aria-label="Permalink to &quot;Retain the direction of each error&quot;">​</a></h2><p>Keep a full three-class confusion matrix beside aggregate results: reference decisions crossed with predicted decisions. Report false allows, allow-to-review and deny-to-review transitions separately, with explicit denominators. A business may need the broader measure of all additional reviews, but it should give that measure a distinct name and definition.</p><p>This also fits the distinction between an execution transcript and an actual outcome in Anthropic&#39;s <a href="https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents" target="_blank" rel="noreferrer">agent-evaluation methodology</a>. That institutional document supplies independently authored methodological context; it does not verify the numerical discrepancy examined here.</p><p>This check applies to allow/review/deny classification; a binary system needs a different specification. It does not test service security, human-review effectiveness or actual queue load. Explaining this discrepancy further requires original predictions, annotations and the calculation version bound to the manuscript. The bounded lesson is to preserve where an error came from before deciding what review costs.</p>',20))])}const w=n(d,[["render",l]]);export{v as __pageData,w as default};
